import { PieChart, Pie, Tooltip, Cell } from "recharts";

function CrimeStats({ crimes }) {
  const counts = crimes.reduce((acc, c) => {
    acc[c.CrimeCode] = (acc[c.CrimeCode] || 0) + 1;
    return acc;
  }, {});

  const chartData = Object.entries(counts).map(([name, value]) => ({ name, value }));

  return (
    <div className="stats">
      <h3>Total Crimes: {crimes.length}</h3>
      <PieChart width={300} height={200}>
        <Pie data={chartData} dataKey="value" nameKey="name" outerRadius={80}>
          {chartData.map((entry, index) => (
            <Cell key={`cell-${index}`} fill={["#8884d8", "#82ca9d", "#ffc658"][index % 3]} />
          ))}
        </Pie>
        <Tooltip />
      </PieChart>
    </div>
  );
}
export default CrimeStats;
